import {portable,loadData,createSolverWorker} from './runtime.js';
import {duration,hoursLabel} from './duration.js';
import {scope,targetScope,ancestors,selectedIds,cumulativeScope,syncNeeds,recommendationCohort,invalidateRecommendations} from './cohorts.js';
import {MODEL_VERSION,MODEL_REVISION,RETIRED_OUTCOMES,ACTIVITIES,LEVELS,SPECIALISMS,NEED_TITLES,profileRequirements,profileLabel,requirementPlacement,crosswalk} from './capability-model.js';
import {measure,scoreFor,timeTotal,eligibility,gapType,coversNeed} from './scoring.js';
import {ROLE_FAMILIES,ROLE_NUMBERING_NOTE,TOOL_TRAINING_EXAMPLES,NEED_DOMAINS} from './model-explanation.js';
import {STORE,createScenario,duplicateScenario,validateScenario,serialize,deserialize,csv} from './storage.js';
import {prepareProblem} from './optimisation.js';
import {PLANNER_RELEASE} from './release.js';

const releaseDate=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(PLANNER_RELEASE.date+'T00:00:00Z'));
const releaseLabel=`Planner v${PLANNER_RELEASE.version} · Released ${releaseDate}`;
document.title=`Cyber / Capability planner · v${PLANNER_RELEASE.version}`;
const data=await loadData('catalogue');
const byId=new Map(data.courses.map(c=>[c.id,c])),needMap=new Map(data.needs.map(n=>[n.id,{...n,title:NEED_TITLES[n.id]||n.title}]));
const $=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>`${(100*x).toFixed(1)}%`,num=x=>Number(x.toFixed(2)),options=(values,current,blank)=>`${blank!==undefined?`<option value="">${esc(blank)}</option>`:''}${values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===current?'selected':''}>${esc(label)}</option>`;}).join('')}`;
const external=(url,label)=>/^https?:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
let loadNotice='';let scenarios=[],activeId;
try{const stored=JSON.parse(localStorage.getItem(STORE)||'null');if(stored){for(const s of stored.scenarios)validateScenario(s,data);scenarios=stored.scenarios;activeId=stored.activeId;}}catch(e){loadNotice='Saved data could not be loaded. It has not been overwritten. Export or repair the saved data before continuing. '+e.message;}
if(!scenarios.length){let s;try{s=await loadData('default-scenario');validateScenario(s,data);s.id=crypto.randomUUID();}catch{s=createScenario(data);}scenarios=[s];activeId=s.id;}
if(!scenarios.some(s=>s.id===activeId))activeId=scenarios[0].id;
let view='overview',cohortId='all',presentation=false,search='',needFilter='',providerFilter='',typeFilter='',toolFilter='',levelFilter='',assessmentFilter='',trackFilter='',maxHours='',requirementFilter='',sort='gain',page=0,busy=false,proposal=null;
const S=()=>scenarios.find(s=>s.id===activeId),C=()=>S().cohorts.find(c=>c.id===cohortId)||S().cohorts[0],readOnly=()=>S().status==='Finalised';
function courses(ids){return ids.map(id=>byId.get(id)).filter(Boolean);}
function save(){if(loadNotice)return;try{localStorage.setItem(STORE,JSON.stringify({scenarios,activeId}));}catch(e){toast('Could not save in this browser. Export the scenario to keep your work.');}}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6500);}
function editable(){if(readOnly()){toast('This plan is finalised. Duplicate it to create an editable draft.');return false;}if(busy){toast('Wait for the recommendation or cancel it before editing.');return false;}return true;}
function changed(){proposal=null;syncNeeds(data,S());save();render();}
function planningChanged(){invalidateRecommendations(S(),C());changed();}
function audience(c=C()){return recommendationCohort(data,S(),c);}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function bandClass(b){return b==='Full'||b==='Strong'?'green':b==='Partial'?'amber':'red';}
function pill(s,cl=''){return `<span class="pill ${cl}">${esc(s)}</span>`;}
function internalStatusLabel(i){return i.status==='Ready'?'Ready for delivery':i.status==='In development'?'In development':'To be built';}
function internalBadges(i){return `<span class="internal-badges">${pill(internalStatusLabel(i),i.status==='Ready'?'internal-ready':'build-needed')}${pill('Not in catalogue','internal-origin')}</span>`;}
function internalSummary(items){if(!items.length)return '';const pending=items.filter(i=>i.status!=='Ready'),ready=items.length-pending.length;return `<div class="internal-summary">${pending.length?pill(`${pending.length} ${pending.length===1?'item needs':'items need'} development`,'build-needed'):''}${ready?pill(`${ready} ready for delivery`,'internal-ready'):''}<small>Not in catalogue · ${timeText({hours:items.reduce((n,i)=>n+(i.hours??0),0),unknown:items.filter(i=>i.hours===null).length})} planned learner time</small></div>`;}
function internalPreview(i){return `<div class="internal-preview">${internalBadges(i)}<small><strong>${esc(i.title)}</strong> · ${i.hours===null?'Time unresolved':hoursLabel(i.hours)}</small></div>`;}
function timeText(t){return `${hoursLabel(t.hours)}${t.unknown?` + ${t.unknown} unresolved`:''}`;}
function internalItems(s,c){return [...new Map([...ancestors(s,c),c].flatMap(x=>x.internal).map(i=>[i.id,i])).values()];}
function metrics(s,c){const ids=selectedIds(s,c),cs=courses(ids),reqs=scope(data,c,s),m=measure(reqs,cs,data.thresholds),cum=measure(cumulativeScope(data,s,c),cs,data.thresholds),inherited=selectedIds(s,c,false),own=courses(c.selected.filter(id=>!inherited.includes(id))),time=timeTotal(cs,s.overrides),inc=timeTotal(own,s.overrides),items=internalItems(s,c),ih=items.reduce((a,i)=>a+(i.hours??0),0),iu=items.filter(i=>i.hours===null).length;
 return {ids,cs,reqs,m,cum,time,inc,items,ih,iu,total:{hours:time.hours+ih,unknown:time.unknown+iu+(ids.filter(id=>!byId.has(id)).length)}};}
function cohortOptions(){return options(S().cohorts.map(c=>[c.id,`${c.group} · ${c.name}`]),C().id);}
function stat(value,label){return `<div class="stat"><strong>${value}</strong><span>${label}</span></div>`;}
function courseLink(c){return `<button class="text-button course-title" data-action="course" data-id="${esc(c.id)}">${esc(c.title)}</button><small>${esc(c.id)} · ${esc(c.provider)}</small>`;}
function warnings(){return validateScenario(S(),data);}
function render(){
 clearTimeout(searchTimer);
 document.body.classList.toggle('presentation',presentation);
 const names={model:['01','Capability model'],overview:['02','Plan overview'],planner:['03','Cohort planner'],gaps:['04','Coverage & gaps'],catalogue:['05','Full catalogue']};
 $('#app').innerHTML=`<aside class="rail"><div class="brand"><span class="brand-mark">c</span><span>cyber<span class="muted"> / capability</span></span></div><div class="eyebrow" style="margin:0 12px 16px">WORKFORCE PLANNING</div><nav>${Object.entries(names).map(([id,[n,title]])=>`<button class="nav-button ${view===id?'active':''}" data-action="view" data-id="${id}"><span class="nav-index">${n}</span>${title}</button>`).join('')}</nav><div class="rail-label">CURRENT COHORT</div><select aria-label="Current cohort" id="cohort-nav">${cohortOptions()}</select><div class="rail-label">PLANNING PRINCIPLES</div><div class="rail-footer">Equal weight per need<br>Evidence, not completion<br>Full-course learning time<br><br><strong>${data.courses.length}</strong> resources · <strong>${data.requirements.length}</strong> requirements<br>Assessment: ${data.assessmentDate}<br>Local workspace · no cloud sync${portable?'<br><br>Portable HTML<br>Export scenario JSON to back up or share your plan. Browser autosave depends on this file location.':''}</div></aside>
 <div class="workspace"><header class="topbar"><div class="topbar-left"><span class="eyebrow">SCENARIO</span><select aria-label="Scenario" id="scenario-select">${options(scenarios.map(s=>[s.id,s.name]),activeId)}</select>${pill(S().status,S().status==='Finalised'?'green':'blue')}</div><div class="actions"><button data-action="presentation">${presentation?'Exit presentation':'Present'}</button><details class="menu edit-only"><summary>Scenario & exports ▾</summary><div class="menu-items"><button data-action="scenario-settings">Name, status & assumptions</button><button data-action="new">New blank scenario</button><button data-action="duplicate">Duplicate as draft</button><button data-action="compare">Compare scenarios</button><button data-action="export-json">Export reloadable JSON</button><button data-action="import">Import scenario JSON</button><button data-action="export-courses">Export course plan CSV</button><button data-action="export-gaps">Export gap register CSV</button><button data-action="print">Print / save plan as PDF</button></div></details><button data-action="print" class="${presentation?'':'edit-only'}">Print plan</button></div></header>
 <div class="planner-release" aria-label="Planner release"><strong>Planner v${esc(PLANNER_RELEASE.version)}</strong><span>Released <time datetime="${esc(PLANNER_RELEASE.date)}">${esc(releaseDate)}</time></span><small>Offline copy · compare with the latest shared release.</small></div>
 <main class="content">${loadNotice?`<div class="banner error">${esc(loadNotice)}</div>`:''}${warnings().map(w=>`<div class="banner warn">${esc(w)}</div>`).join('')}${readOnly()?'<div class="banner">Finalised snapshot. Duplicate this scenario to make changes.</div>':''}${S().schema===1?'<div class="banner warn"><strong>Previous capability model.</strong> This saved plan retains its original scope. Create a new plan to choose independent agentic levels and role specialisms; its selections must be planned afresh. <button class="small edit-only" data-action="new">Create a plan with the current model</button></div>':''}${view==='model'?modelView():view==='overview'?overview():view==='planner'?planner():view==='gaps'?gaps():catalogue()}</main><section class="print-only">${printPlan()}</section></div>`;
}
function overview(){const shared=(S().schema===2?['all','entry','practitioner','technical']:['all','practitioner','technical']).map(id=>S().cohorts.find(c=>c.id===id)).filter(Boolean);
 return `<div class="hero"><div><div class="eyebrow">THE AGENTIC CYBER WORKFORCE</div><h1>Build capability. Make the gaps visible.</h1><p>Foundation + agentic level + relevant role specialisms + tool training. Choose target learning needs with your functional heads.</p></div><button class="primary edit-only" data-action="open-cohort" data-id="all">Explore the foundation →</button></div>
 <p><button class="text-button" data-action="view" data-id="model">Read the capability model →</button></p><div class="cards shared-cards">${shared.map((c,i)=>{const m=metrics(S(),c);return `<article class="card"><div class="stage">0${i+1} / ${c.profile?(c.profile.level===0?'Common knowledge':`Agentic level L${c.profile.level}`):'Previous model'}</div><h2>${esc(c.name)}</h2><div class="metric">${pct(m.m.coverage)} <small>assessed coverage</small></div><div class="bar"><span style="width:${m.m.coverage*100}%"></span></div><p class="muted">${c.selected.length} selected · ${timeText(m.inc)} / ${hoursLabel(c.budget)} course budget</p>${internalSummary(c.internal)}<div class="card-footer"><span>${pill(m.m.critical+' critical gaps',m.m.critical?'amber':'green')}</span><button class="text-button" data-action="open-cohort" data-id="${c.id}">Review pathway →</button></div></article>`;}).join('')}</div>
 <div class="legend"><span><span class="dot"></span>Coverage uses the best score per requirement</span><span><span class="dot amber"></span>Critical gap = a must-have requirement at 0</span><span>${pill("To be built","build-needed")} Internal learning outside the catalogue; no assessed coverage credit</span></div>
 <div class="section-title"><h2>Pathways for the organisation</h2><span class="muted">Alternatives within a function — not one assignment for everyone</span></div>${table(['Cohort / specialism','Layer coverage','Critical gaps','Additional courses','Cumulative commitment'],cohortRows())}
 <div class="banner"><strong>How to read this plan.</strong> Percentages describe syllabus evidence, not demonstrated competence. Additional courses are optimised against each layer’s needs. Cumulative commitment includes inherited courses and planned internal work once. Specialist branches are alternatives.</div>
 <div class="section-title"><h2>Working assumptions</h2><button class="text-button edit-only" data-action="scenario-settings">Edit assumptions</button></div><div class="panel"><p>${esc(S().assumptions)}</p><small>Source: ${esc(data.filename)} · snapshot ${data.version}. Previous catalogue versions are archived.</small></div>`;
}
function cohortRows(){let group='';return S().cohorts.flatMap(c=>{const m=metrics(S(),c),rows=[];if(c.group!==group){group=c.group;rows.push(`<tr class="group-row"><td colspan="5">${esc(group)}</td></tr>`);}rows.push(`<tr><td><button class="text-button" data-action="open-cohort" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.profile?profileLabel(c):c.needs.join(', '))}${c.parent?' · inherits '+esc(S().cohorts.find(x=>x.id===c.parent)?.name):''}</small>${c.selected.length?`<details class="overview-courses"><summary>${c.selected.length} selected resources</summary>${c.selected.map(id=>`<div><button class="text-button" data-action="course" data-id="${id}">${esc(id+' · '+(byId.get(id)?.title||'Unresolved'))}</button></div>`).join('')}</details>`:''}${c.internal.length?`<details class="overview-internal"><summary>${c.internal.length} internal ${c.internal.length===1?'item':'items'} · not in catalogue</summary>${c.internal.map(internalPreview).join('')}</details>`:''}</td><td>${pct(m.m.coverage)}<div class="bar"><span style="width:${m.m.coverage*100}%"></span></div></td><td>${pill(m.m.critical,m.m.critical?'amber':'green')}</td><td>${timeText(m.inc)}<small>${c.selected.length} selected · ${hoursLabel(c.budget)} budget</small></td><td><strong>${timeText(m.total)}</strong><small>${timeText(m.time)} courses + ${hoursLabel(m.ih)} internal${m.iu?' + unknown internal time':''}</small>${internalSummary(m.items)}</td></tr>`);return rows;});}
function planner(){const c=C(),m=metrics(S(),c),inherited=courses(selectedIds(S(),c,false));
 return `<div class="hero"><div><div class="eyebrow">${esc(c.group)} / COHORT PLANNER</div><h1>${esc(c.name)}</h1><p>${esc(c.note||'Choose learning for this responsibility, then plan the internal work that the catalogue cannot supply.')}</p></div><div class="actions edit-only">${c.profile?'<button data-action="profile">Level, roles & tools</button>':''}<button data-action="scope">Learning outcomes</button></div></div>${c.profile?profileSummary(c):''}${c.needsReview?'<div class="banner warn">Planning inputs changed. Coverage is recalculated; review this selection or generate and apply a fresh recommendation. <button data-action="review-selection" class="small edit-only">Record selection review</button></div>':''}
 <div class="panel"><div class="controls edit-only"><label>Additional course budget (hours)<input id="budget" type="number" min="0" step=".25" value="${c.budget}" ${readOnly()?'disabled':''}></label><button class="primary" data-action="recommend" ${busy||readOnly()?'disabled':''}>${busy?'Finding the best combination…':'Recommend within budget'}</button>${busy?'<button data-action="cancel-solve">Cancel</button>':''}<button data-action="eligibility">Recommendation filters</button></div><div class="stats">${stat(pct(m.m.coverage),'Coverage of this layer')}${stat(timeText(m.inc),'Additional course hours')}${stat(timeText(m.total),'Cumulative learner commitment')}${stat(m.m.critical,'Critical requirements at 0')}</div><small>${m.reqs.length} applicable requirements · ${pct(m.cum.coverage)} coverage across the full inherited pathway</small></div>
 ${m.inc.hours>c.budget?'<div class="banner warn">Current selection exceeds the layer budget. It remains selected until you change it.</div>':''}${proposal?proposalPanel():''}
 <div class="split"><section><div class="section-title"><h2>Selected for this layer</h2><button class="text-button edit-only" data-action="view" data-id="catalogue">Browse all resources →</button></div><div class="selected-list">${c.selected.length?c.selected.map(id=>selectedCard(id,false)).join(''):'<div class="panel empty">No courses selected yet.<br>Recommend a combination or browse the catalogue.</div>'}</div>
 <div class="section-title"><h2>Internal learning & practice</h2><button class="small edit-only" data-action="internal-new">+ Add item</button></div><p class="inline-note">These items are <strong>not in the catalogue</strong>. Items marked <strong>To be built</strong> or <strong>In development</strong> need development before delivery. Their learner hours are included in the plan; they do not increase assessed coverage.</p><div class="selected-list">${internalCards()}</div>
 <div class="section-title"><h2>Courses that add coverage</h2><label>Sort <select id="sort">${options([['gain','Additional coverage'],['standalone','Standalone coverage']],sort)}</select></label></div>${candidateTable(false)}</section>
 <aside class="sticky-side"><div class="panel"><h3>Inherited learning</h3><p class="muted">Courses already selected in earlier layers contribute coverage without using this layer’s budget.</p><div class="selected-list">${inherited.length?inherited.map(x=>selectedCard(x.id,true)).join(''):'<small>No inherited courses selected.</small>'}</div>${m.items.filter(i=>!c.internal.some(own=>own.id===i.id)).length?`<div class="layout-gap"></div><h3>Inherited internal work</h3><p class="inline-note">Included once in cumulative learner time; no assessed coverage credit.</p>${m.items.filter(i=>!c.internal.some(own=>own.id===i.id)).map(internalPreview).join('')}`:''}<div class="layout-gap"></div><h3>Need-level coverage</h3>${m.m.needs.map(n=>`<p><small>${n.id} · ${esc(needMap.get(n.id)?.title)}</small><br><strong>${pct(n.coverage)}</strong> ${pill(n.band,bandClass(n.band))}</p>`).join('')}<button data-action="view" data-id="gaps">Inspect remaining gaps →</button></div></aside></div>`;
}
function selectedCard(id,inherited){const c=byId.get(id);if(!c)return `<div class="selection">Unresolved course ${esc(id)} <button class="small edit-only" data-action="remove" data-id="${esc(id)}">Remove</button></div>`;const d=duration(c,S().overrides),m=metrics(S(),C()),without=measure(m.reqs,m.cs.filter(x=>x.id!==id),data.thresholds),contribution=(m.m.coverage-without.coverage)*100;return `<div class="selection ${inherited?'inherited':''}"><div class="selection-top"><div>${courseLink(c)}</div><span class="pill">${d.hours===null?'Time unresolved':hoursLabel(d.hours)}</span></div><small>${esc(c.duration)}${Object.hasOwn(S().overrides,id)?' · planner estimate':''}</small>${!inherited?`<p class="inline-note"><strong>${contribution.toFixed(1)} percentage points</strong> of unique layer coverage in this selection. ${esc(c.limitations)}</p><div class="actions edit-only"><button class="small" data-action="pin" data-id="${id}">${C().pinned.includes(id)?'Unpin':'Pin to keep'}</button><button class="small" data-action="estimate" data-id="${id}">Set hours</button><button class="small" data-action="remove" data-id="${id}">Remove</button></div>`:''}</div>`;}
function proposalPanel(){const p=proposal,c=C(),m=metrics(S(),c),inherited=courses(selectedIds(S(),c,false)),next=measure(m.reqs,[...inherited,...courses(p.ids)],data.thresholds),t=timeTotal(courses(p.ids),S().overrides);return `<div class="banner"><strong>${esc(p.message)}</strong><p>Coverage ${pct(m.m.coverage)} → <strong>${pct(next.coverage)}</strong> · additional course time ${timeText(m.inc)} → <strong>${timeText(t)}</strong> · critical gaps ${m.m.critical} → ${next.critical}</p><p>${p.ids.map(id=>esc(id)+' — '+esc(byId.get(id)?.title)).join('<br>')||'No additional course is needed or feasible under these constraints.'}</p><small>${p.gap!==null?'Solver gap: '+esc(p.gap):'Solver gap not exposed by this solver build.'} Your existing selection is unchanged until you apply this proposal.</small><div class="actions edit-only" style="margin-top:12px"><button class="primary" data-action="apply-proposal">Apply proposed selection</button><button data-action="discard-proposal">Keep current selection</button></div></div>`;}
function internalCards(){return C().internal.length?C().internal.map(i=>`<div class="selection internal-item ${i.status==='Ready'?'internal-item-ready':'internal-item-pending'}"><div class="internal-item-heading">${internalBadges(i)}<h3>${esc(i.title)}</h3></div><p>${esc(i.outcomes)}</p><small>${esc(i.owner||'Owner not assigned')} · ${i.hours===null?'Time unresolved':hoursLabel(i.hours)} · ${esc(i.requirements.join(', '))}</small><div class="actions edit-only"><button class="small" data-action="internal-edit" data-id="${i.id}">Edit</button><button class="small" data-action="internal-remove" data-id="${i.id}">Remove</button></div></div>`).join(''):'<div class="panel empty">Plan an in-house item to address the remaining gaps. It will be labelled To be built and Not in catalogue.<br>Planned work does not increase assessed coverage.</div>';}
function candidateData(){const c=C(),m=metrics(S(),c),inherited=selectedIds(S(),c,false),remaining=c.budget-m.inc.hours,eligibleC=audience(c);return data.courses.map(x=>{const reason=eligibility(x,eligibleC,S().overrides),gain=measure(m.reqs,[...m.cs,x],data.thresholds).coverage-m.m.coverage,standalone=measure(m.reqs,[x],data.thresholds).coverage,h=duration(x,S().overrides).hours;return {course:x,gain,standalone,h,reason,status:inherited.includes(x.id)?'Inherited':c.selected.includes(x.id)?'Selected':reason|| (h>remaining?'Over remaining budget':gain<1e-9?'Overlapping / no additional coverage':'Adds coverage')};});}
function filteredCandidates(all){return candidateData().filter(({course:c,gain,reason})=>{
 if(!all&&(C().selected.includes(c.id)||selectedIds(S(),C(),false).includes(c.id)||gain<1e-9||reason))return false;
 if(trackFilter&&c.track!==trackFilter)return false;
 if(search&&!`${c.id} ${c.title} ${c.provider} ${c.description}`.toLowerCase().includes(search.toLowerCase()))return false;
 if(needFilter&&!coversNeed(c,needFilter,data.requirements))return false;
 if(providerFilter&&c.provider!==providerFilter||typeFilter&&c.type!==typeFilter||toolFilter&&c.tool!==toolFilter||levelFilter&&c.level!==levelFilter)return false;
 if(assessmentFilter==='assessed'&&!Object.keys(c.scores).length||assessmentFilter==='unassessed'&&Object.keys(c.scores).length)return false;
 const h=duration(c,S().overrides).hours;if(maxHours!==''&&(h===null||h>+maxHours))return false;
 if(requirementFilter&&(c.scores[requirementFilter]?.score||0)<=scoreFor(metrics(S(),C()).cs,requirementFilter))return false;
 return true;
 }).sort((a,b)=>(sort==='gain'?b.gain-a.gain:b.standalone-a.standalone)||(a.h??Infinity)-(b.h??Infinity)||a.course.id.localeCompare(b.course.id));}
function candidateTable(all){const results=filteredCandidates(all),limit=all?30:8,shown=results.slice(all?page*limit:0,all?(page+1)*limit:limit);return `${table(['Learning resource','Coverage contribution','Learning time','Decision / action'],shown.map(x=>`<tr><td>${courseLink(x.course)}<small>${esc(x.course.type)} · Source audience: ${esc(x.course.level)}</small></td><td><strong>+${(x.gain*100).toFixed(1)} pp</strong><small>${pct(x.standalone)} standalone</small></td><td>${x.h===null?pill('Unresolved','amber'):hoursLabel(x.h)}<small>${esc(x.course.duration)}</small></td><td>${pill(x.status,x.status==='Adds coverage'?'green':x.status==='Selected'?'blue':'')}<div class="actions edit-only" style="margin-top:9px"><button class="small" data-action="preview" data-id="${x.course.id}">Preview</button>${C().selected.includes(x.course.id)?`<button class="small" data-action="remove" data-id="${x.course.id}">Remove</button>`:selectedIds(S(),C(),false).includes(x.course.id)?'':`<button class="small" data-action="add" data-id="${x.course.id}">Add</button>`}<button class="small" data-action="exclude" data-id="${x.course.id}">${C().excluded.includes(x.course.id)?'Allow':'Exclude'}</button></div></td></tr>`))}${!shown.length?'<div class="empty">No resources match these criteria.</div>':''}${all?`<div class="section-title"><small>${results.length} results · page ${page+1} of ${Math.max(1,Math.ceil(results.length/limit))}</small><div class="actions"><button class="small" data-action="previous" ${page===0?'disabled':''}>Previous</button><button class="small" data-action="next" ${(page+1)*limit>=results.length?'disabled':''}>Next</button></div></div>`:''}`;}
function catalogue(){return `<div class="hero"><div><div class="eyebrow">${data.courses.length} RESOURCES / FULL CATALOGUE</div><h1>Find the right learning.</h1><p>Compare every resource against <strong>${esc(C().name)}</strong>. Additional coverage accounts for the current selection and inherited courses.</p></div></div>
 ${requirementFilter?`<div class="banner">Showing courses that improve <strong>${esc(requirementFilter)}</strong>. <button class="small" data-action="clear-filters">Clear filters</button></div>`:''}
 <div class="filters"><input aria-label="Search courses" id="search" type="search" value="${esc(search)}" placeholder="Search course, provider or topic…"><select aria-label="Need filter" id="need-filter">${options(data.needs.map(n=>[n.id,`${n.id} · ${needMap.get(n.id).title}`]),needFilter,'All needs')}</select><select aria-label="Audience filter" id="level-filter">${options([['Base','Foundation (source: Base)'],['Entry','Entry (source audience)'],['Practitioner','Practitioner (source audience)'],['Expert','Expert (source audience)'],['Unknown','Unknown']],levelFilter,'All source audiences')}</select><select aria-label="Provider filter" id="provider-filter">${options([...new Set(data.courses.map(c=>c.provider))].sort(),providerFilter,'All providers')}</select><select aria-label="Resource type" id="type-filter">${options([...new Set(data.courses.map(c=>c.type))].sort(),typeFilter,'All resource types')}</select><select aria-label="Tool dependency" id="tool-filter">${options([...new Set(data.courses.map(c=>c.tool).filter(Boolean))].sort(),toolFilter,'All tools / dependencies')}</select><select aria-label="Training type" id="track-filter">${options([['general','Assessed learning catalogue'],['tool','Tool training']],trackFilter,'All training')}</select><select aria-label="Assessment filter" id="assessment-filter">${options([['assessed','Assessed'],['unassessed','Unassessed']],assessmentFilter,'Any assessment status')}</select><input aria-label="Maximum course hours" id="max-hours" type="number" min="0" value="${esc(maxHours)}" placeholder="Max hours" style="width:110px"><select aria-label="Sort courses" id="sort">${options([['gain','Additional coverage'],['standalone','Standalone coverage']],sort)}</select><button class="small" data-action="clear-filters">Reset</button></div><p class="inline-note">Catalogue filters affect this list. Recommendation filters are configured separately in the cohort planner. Unassessed tool-training metadata does not supply coverage scores.</p><div id="catalogue-results">${candidateTable(true)}</div>`;}
function gaps(){const c=C(),m=metrics(S(),c),full=measure(m.reqs,data.courses,data.thresholds),counts={};for(const r of m.m.rows){const label=gapType(r.score,scoreFor(data.courses,r.id));counts[label]=(counts[label]||0)+1;}
 return `<div class="hero"><div><div class="eyebrow">${esc(c.name)} / EVIDENCE & GAPS</div><h1>What is covered. What comes next.</h1><p>Compare selected learning with the assessed catalogue ceiling. Planned internal work remains separate from evidence.</p></div><button class="edit-only" data-action="internal-new">+ Plan internal work</button></div><div class="panel"><div class="stats">${stat(pct(m.m.coverage),'Selected course coverage')}${stat(pct(full.coverage),'Assessed catalogue ceiling')}${stat(m.m.full+'/'+m.reqs.length,'Requirements at score 3')}${stat(m.m.critical,'Critical requirements at 0')}</div><div class="chips">${Object.entries(counts).map(([s,n])=>`<span class="chip">${n} · ${esc(s)}</span>`).join('')}</div></div><p class="inline-note">The ceiling includes all recorded course evidence, even resources outside this cohort’s filters. A score of 3 means the syllabus evidences full coverage; it does not certify learner competence. Unassessed resources may offer further coverage.</p>
 ${m.m.needs.map(n=>`<details class="need-box"><summary><span class="mono">${n.id}</span><strong class="need-name">${esc(needMap.get(n.id)?.title)}</strong><div class="bar"><span style="width:${n.coverage*100}%"></span></div><span>${pct(n.coverage)}</span>${pill(n.band,bandClass(n.band))}${n.critical?pill(n.critical+' critical gaps','amber'):''}</summary>${table(['Requirement','Selected evidence','Catalogue ceiling / next step','Planned internal work'],n.rows.map(r=>gapRow(r,m)))}</details>`).join('')}
 <div class="banner warn">“No assessed teaching found” means the requirement is not taught in the assessed evidence in this catalogue. It is not a claim that no training exists. ${data.courses.filter(c=>!Object.keys(c.scores).length).length} resources have no requirement-level scores.</div>`;
}
function gapRow(r,m){const best=scoreFor(data.courses,r.id),label=gapType(r.score,best),improvers=data.courses.filter(c=>(c.scores[r.id]?.score||0)>r.score),allowed=improvers.filter(c=>!eligibility(c,audience(),S().overrides)),within=allowed.filter(c=>(duration(c,S().overrides).hours??Infinity)<=C().budget-m.inc.hours),items=m.items.filter(i=>i.requirements.includes(r.id));return `<tr><td><strong>${r.id} · ${esc(r.title)}</strong>${r.core?' '+pill('Must-have'):''}<small>${esc(r.description)}</small><small>Rubric row ${r.source.row} · ${esc(requirementPlacement(r))}</small></td><td><strong>${r.score} / 3</strong><small>${r.assessed?'Recorded assessment':'Unassessed in selected courses'}</small>${r.witnesses.map(c=>`<button class="text-button" data-action="course" data-id="${c.id}">${c.id}</button><div class="evidence">${esc(c.scores[r.id]?.evidence)}</div>`).join('')}</td><td class="gap-cell">${pill(label,best<3?'amber':r.score===3?'green':'blue')}<small>Best recorded score: ${best}/3${best===0?' · no evidenced coverage':best===1?' · mention only':''}</small>${improvers.length?`<small>${improvers.length} resources improve this · ${allowed.length} eligible · ${within.length} within remaining hours</small><button class="text-button" data-action="supplements" data-id="${r.id}">See supplementary courses →</button>`:''}</td><td>${items.length?items.map(internalPreview).join(''):'<small>Not planned</small>'}<button class="text-button edit-only" data-action="internal-for" data-id="${r.id}">Plan internal work</button></td></tr>`;}

function modelView(){return `<div class="hero"><div><div class="eyebrow">CAPABILITY MODEL / VERSION ${MODEL_VERSION} · REVISION ${MODEL_REVISION}</div><h1>Foundation. Levels. Roles. Tools.</h1><p>Everyone shares a foundation. Their remaining learning depends on how they work with agents, their role, and the tools they use.</p></div><button data-action="export-crosswalk">Export outcome crosswalk</button></div>
 <div class="model-formula">Foundation <span>+</span> Agentic level <span>+</span> Relevant role specialisms <span>+</span> Tool training</div>
 <div class="model-components">${[['Foundation','What should everyone understand?','AI, agents, limitations, risks, threats and responsible use. Shared by everyone; not a fourth level.'],['Agentic level','How will this person work with agents?','L1: work with AI assistance. L2: supervise agents. L3: build and evaluate agents.'],['Role specialisms','What does the job require?','Governance, leadership, IAM, security, engineering and other responsibilities, independently of agentic level.'],['Tool training','Which tools must they operate?','How to use a specific product, platform or in-house tool, assigned according to access and intended work.']].map(([name,question,description])=>`<article class="panel"><h2>${name}</h2><strong>${question}</strong><p>${description}</p></article>`).join('')}</div>
 <div class="section-title"><h2>Agentic levels — how people work with agents</h2></div>${table(['Level','Target capability'],LEVELS.slice(1).map(l=>`<tr><td><strong>${esc(l.name)}</strong></td><td>${esc(l.description)}</td></tr>`))}
 <div class="banner"><strong>The L2/L3 boundary:</strong> L2 operates and adapts an existing agent workflow and runs task checks. L3 designs the agent’s behaviour and its evaluation approach, including no-code/low-code builds. Shared agent infrastructure is a learning need within Security architecture &amp; engineering, selected for people with that responsibility.</div>
 <p>Levels describe agentic capability, not seniority, professional expertise or operational permission. Higher levels build on shared capabilities; demonstrated capabilities need not be retaught. Everyone does not need to reach L3. The existing cyber curriculum remains a prerequisite.</p>
 <div class="section-title"><h2>Role specialisms — what the job requires</h2></div><p>Role specialisms add capabilities for the responsibilities of the <strong>nine roles already defined in this model</strong>. They retain the project's grouping of ${external('https://www.enisa.europa.eu/publications/european-cybersecurity-skills-framework-role-profiles','ENISA ECSF profiles')}, including Leadership and the explicit Vulnerability &amp; exposure management and IAM roles.</p>${table(['Defined role','ECSF reference in the existing model'],ROLE_FAMILIES.map(r=>`<tr><td>${r.id}. ${esc(r.name)}</td><td>${esc(r.ecsf)}</td></tr>`))}<p>${esc(ROLE_NUMBERING_NOTE)}</p><p>Select the relevant outcomes for actual responsibilities; a person can work across roles and need several specialisms at any agentic level. Specialist depth follows the responsibility. A role does not require a new specialist module when shared capabilities and tool training meet its needs. Application-security code-analysis and harness requirements are already covered by R4.2 within Vulnerability &amp; exposure management.</p>
 <div class="section-title"><h2>Tool training — how people use their approved tools</h2></div><p><strong>Tool training teaches someone how to use a specific product, platform or in-house tool.</strong> Its audience follows tool distribution and intended work: everyone if the tool is deployed to everyone, users across several functions, or a specialist group. People with access receive training for the tasks they are expected to perform; the same product can require different training for users, supervisors and builders.</p>${table(['Who needs the tool training','What the training teaches'],TOOL_TRAINING_EXAMPLES.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`))}<p>The named examples use ${external('https://learn.microsoft.com/en-us/microsoft-365/copilot/cowork/get-started','Microsoft Copilot Cowork')}, Anthropic Claude Code and ${external('https://www.anthropic.com/news/claude-code-security','Claude Code Security')}. They apply where products are approved and access is provided; they do not imply deployment in the bank.</p><p>Operating an existing vulnerability-finding tool is distinct from designing its harness and evaluation approach. The latter needs L3 capabilities and the application-security specialism as well as training on the chosen development tools. Tool familiarity alone does not demonstrate those capabilities or grant operational permission.</p>
 <div class="section-title"><h2>From the model to learning needs</h2></div><div class="panel"><p>The model defines a person’s <strong>target capability profile</strong>. The next step is to translate that profile into <strong>learning needs</strong>: the topics they need to learn, such as supervising agents or assessing AI risk. Each need contains <strong>learning outcomes</strong>: specific statements of what someone must know or do. These outcomes connect the model to training selection and assessment.</p><p>For example, a GRC practitioner supervising assessment agents needs the Foundation, shared capabilities through L2, relevant governance outcomes and practice on the approved tools. N7 (Supervising agents) includes verifying outputs and tracing evidence (N7.3), and stopping or taking over a task (N7.4). Their governance responsibilities may also require AI risk assessment (N13.2). A practical exercise in their assessment tool can address these outcomes together.</p><p>Need IDs such as N7 and R9.1 identify topics; outcome IDs such as N7.3 and R9.1.1 identify the detailed requirements underneath them. Select applicable outcomes, including where a need spans more than one component of the model.</p><p>Compare the target outcomes with demonstrated current capability to identify what still needs to be learned. Without a baseline assessment, these are <strong>target learning needs</strong>, not measured skill gaps. Demonstrated outcomes need not be retaught.</p></div>
 <div class="panel"><h3>Essential outcomes and depth</h3><p>N4 covers responsible use for any bank employee. N5 adds cyber-specific awareness for all cyber staff: <strong>N5.8 introduces the main AI security risk families</strong>, while <strong>N5.4 retains examples of attacks on the bank’s AI</strong>. N5.1 combines social engineering and deepfake impersonation at awareness depth; the former N5.2 is retired. Foundation uses a brief recognition, verification and escalation segment within the bank session. The full INT-2787 social-engineering course is excessive for this audience. N12.1 provides specialist threat-modelling depth.</p><p>A must-have is essential to the assigned objective. N11.3 is essential when automated judges are used; R6.1.2 when assurance work itself uses AI. Record these activities in the profile editor. Detailed identity delegation (R9.1.2) belongs to identity integration; least privilege is essential for identity operations. N6.4 is Accountability. N8 retains Skill terminology.</p><p>Catalogue v11 reassesses the four new or substantively changed outcomes. Other outcome evidence and the 23 scoring groups are preserved. Proposed internal training receives no coverage credit until assessed.</p></div><div class="section-title"><h2>Generic and cyber-specific learning needs</h2></div><p><strong>Generic</strong> needs transfer across functions: using, supervising, building or evaluating agents, responsible use, AI governance and leading adoption. Generic does not mean required by everyone; the target level and responsibilities determine applicability.</p><p><strong>Cyber-specific</strong> needs concern cybersecurity work, threats, controls or specialist practices. They can still serve a broad audience: N1 and the foundation outcomes in N5 are shared across this cyber workforce, and basic threat awareness can serve staff outside cyber.</p><p>Classification follows the primary learning objective. Organisation-specific policies and cyber examples can contextualise generic capabilities without changing their category. N3 prompt-injection awareness and N4 safe use are generic user capabilities; N12 security design and the R-coded security responsibilities require cyber depth.</p><p><strong>${data.needs.filter(n=>NEED_DOMAINS[n.id].kind==='Generic').length} generic needs and ${data.needs.filter(n=>NEED_DOMAINS[n.id].kind==='Cyber-specific').length} cyber-specific needs.</strong> N0 core craft is a cyber-specific prerequisite outside these ${data.needs.length} assessed needs.</p>${table(['Need','Content category','Why / how it is applied'],data.needs.map(n=>`<tr><td>${esc(n.id)} · ${esc(needMap.get(n.id).title)}</td><td>${pill(NEED_DOMAINS[n.id].kind,'blue')}</td><td>${esc(NEED_DOMAINS[n.id].reason)}</td></tr>`))}<p>Teach reusable generic capabilities together, then add cyber cases, specialist outcomes and tool practice for each audience. For application security, N7 and N9 supply generic supervision and task checks; N10–N11 supply generic building and evaluation; R4.2 adds cyber-specific code-analysis and vulnerability-validation capabilities. The classification does not change applicability, outcome IDs, scoring groups or assessment evidence.</p>
 ${table(['Example profile','Learning combination'],[['GRC supervising assessment agents','Foundation + L2 + relevant governance outcomes + tools'],['GRC building assessment agents','Foundation + L3 + relevant governance outcomes + tools'],['IAM administering agent identities manually','Foundation + L1 + identity operations + tools'],['Leader setting adoption priorities','Foundation + actual agentic level + relevant leadership, governance and vendor evaluation + tools']].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`))}
 <div class="section-title"><h2>From target work to a training plan</h2></div><div class="panel"><p><strong>Target work → Capability profiles → Learning needs → Training and practice → Cohorts and delivery plan</strong></p><p>The model defines the target capabilities; the learning needs and outcomes specify what to learn. The training plan adds how, with whom and when.</p><ol><li><strong>Define the target work and profile.</strong> Describe future tasks, responsibilities and boundaries, then choose the agentic level, relevant role specialisms and approved tools.</li><li><strong>Identify the learning needs.</strong> Select the applicable generic and cyber-specific outcomes and compare them with demonstrated current capability, where evidence is available.</li><li><strong>Match training and practice.</strong> Find courses, internal learning and realistic exercises that address those outcomes. Assign product-specific training according to tool access and intended work. One resource can address several needs; one need can require several resources.</li><li><strong>Form cohorts around shared needs.</strong> Group people who need the same learning, including across functions. A function can contain several profiles. Count shared courses, outcomes and internal learning once.</li><li><strong>Build the delivery plan.</strong> Sequence learning against priorities and prerequisites, then schedule it within learner time and delivery capacity. Include tool practice and internal learning still to be developed.</li><li><strong>Check readiness.</strong> Assess what people can demonstrate after learning. Course coverage is evidence about the syllabus; learner competence and operational permission are separate decisions.</li></ol><p>Tool metadata and planned internal work do not create assessed course coverage.</p></div>
 <div class="section-title"><h2>Role learning needs reference</h2></div><p>These packages collect learning needs within the defined roles. Agent infrastructure belongs within Security architecture &amp; engineering: N10.3 covers engineering at scale, N10.6 building MCP servers, and N10.7 shared Skills infrastructure. These outcomes remain part of N10; they add no new role or scored need. AI threat tracking belongs within Threat intelligence &amp; detection: N5.7 covers tracking the AI threat landscape and adjusting controls. It remains within N5 for assessment, with specialist depth beyond the shared foundation awareness. Select role outcomes for the relevant responsibilities and check prerequisites independently of agentic level.</p>${table(['Role learning needs','Existing outcomes'],SPECIALISMS.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.requirements.join(', '))}</td></tr>`))}
 <div class="section-title"><h2>Learning needs and outcome crosswalk</h2></div><p>All ${data.requirements.length} original outcomes and ${data.needs.length} scoring groups are retained. New placement changes applicability; historical source labels remain traceable. Changing a profile recalculates coverage and requires a new review of course choices.</p>${data.needs.map(n=>`<details class="need-box"><summary><strong>${n.id} · ${esc(needMap.get(n.id).title)}</strong> ${pill(NEED_DOMAINS[n.id].kind,'blue')}</summary><p>${esc(NEED_DOMAINS[n.id].reason)}</p>${table(['Outcome','Current placement','Historical source'],data.requirements.filter(r=>r.need===n.id).map(r=>`<tr><td><strong>${r.id} · ${esc(r.title)}</strong><small>${esc(r.description)}</small>${r.core?pill('Must-have'):''}</td><td>${esc(requirementPlacement(r))}</td><td>${esc(r.level)}<small>${esc(r.source.sheet)} row ${r.source.row}</small></td></tr>`))}</details>`).join('')}`;}
function profileSummary(c){return `<div class="panel profile-summary"><strong>${esc(profileLabel(c))}</strong><p>Approved tools: ${c.profile.tools.length?c.profile.tools.map(t=>`<button class="text-button" data-action="profile-tool" data-id="${esc(t)}">${esc(t)}</button>`).join(' · '):'Not assigned — confirm the tools used by this cohort.'} <button class="text-button" data-action="tool-training">Browse tool training →</button></p><p>Recorded activities: ${esc(ACTIVITIES.filter(a=>(c.profile.activities||[]).includes(a.id)).map(a=>a.name).join('; ')||'None recorded')}.</p><small>Target learning needs; no learner baseline assessment is recorded. Tool learning adds practice and time; unassessed metadata provides no coverage points.</small></div>`;}
function profileParents(c,level){return S().cohorts.filter(x=>x.id!==c.id&&x.profile&&!x.profile.specialisms.length&&x.profile.level<=level&&!ancestors(S(),x).some(a=>a.id===c.id));}
function profileDialog(){if(!editable())return;const c=C();if(!c.profile)return;showDialog('Level, roles & tools',`<p>Choose how this cohort works with agents, then its job responsibilities. Role depth is independent of agentic level; confirm prerequisites separately.</p><div class="field-grid"><label>Cohort name<input id="profile-name" value="${esc(c.name)}"></label><label>Agentic level<select id="profile-level">${options(LEVELS.map(l=>[String(l.level),l.name]),String(c.profile.level))}</select></label><label>Inherited shared learning<select id="profile-parent">${options(profileParents(c,c.profile.level).map(p=>[p.id,p.name]),c.parent||'','No inherited selection')}</select></label></div><p class="muted">All lower shared capabilities remain in the target. An inherited selection supplies learning once; without inheritance, this cohort plans the full profile itself.</p><h3>Role specialisms</h3><div class="checkbox-list">${SPECIALISMS.map(r=>`<label><input class="profile-role" type="checkbox" value="${r.id}" ${c.profile.specialisms.includes(r.id)?'checked':''}><span>${esc(r.name)}<small>${esc(r.requirements.join(', '))}</small></span></label>`).join('')}</div><h3>Activities that make additional outcomes essential</h3><div class="checkbox-list">${ACTIVITIES.map(a=>`<label><input class="profile-activity" type="checkbox" value="${a.id}" ${(c.profile.activities||[]).includes(a.id)?'checked':''}><span>${esc(a.name)}<small>${a.requirement}</small></span></label>`).join('')}</div><label>Approved tools used (one per line)<textarea id="profile-tools" placeholder="Confirm approved products and platforms with the functional head">${esc(c.profile.tools.join('\n'))}</textarea></label><div class="field"><label>Reason for this profile<textarea id="profile-rationale">${esc(c.rationale)}</textarea></label></div><p>Existing course selections and manual outcome adjustments are retained for review. Saving recalculates scope and marks this cohort and its descendants for planning review.</p>`,`<button data-action="close">Cancel</button><button class="primary" data-action="profile-save">Save profile</button>`);}
function saveProfile(){const name=$('#profile-name').value.trim(),rationale=$('#profile-rationale').value.trim();if(!name||!rationale){toast('Enter a cohort name and a rationale.');return;}const draft=structuredClone(S()),c=draft.cohorts.find(x=>x.id===C().id);c.name=name;c.profile={activities:[...document.querySelectorAll('.profile-activity:checked')].map(x=>x.value),level:+$('#profile-level').value,specialisms:[...document.querySelectorAll('.profile-role:checked')].map(x=>x.value),tools:[...new Set($('#profile-tools').value.split('\n').map(x=>x.trim()).filter(Boolean))]};c.rank=c.profile.level;c.parent=$('#profile-parent').value||null;c.rationale=rationale;syncNeeds(data,draft);validateScenario(draft,data);invalidateRecommendations(draft,c);Object.assign(S(),draft);closeDialog();changed();}
function outcomeDialog(){const c=C(),active=new Set(targetScope(data,c).map(r=>r.id)),inherited=new Set(ancestors(S(),c).flatMap(a=>targetScope(data,a)).map(r=>r.id));showDialog('Target learning outcomes',`<p>Fine-tune this profile by responsibility. Inherited outcomes are shown checked and are managed in their shared cohort. No learner baseline is recorded: this is applicability, not measured competence.</p><label>Reason for applicability changes<textarea id="scope-rationale">${esc(c.rationale)}</textarea></label><div class="checkbox-list" style="max-height:360px">${data.requirements.map(r=>`<label><input class="outcome-check" type="checkbox" value="${r.id}" ${active.has(r.id)||inherited.has(r.id)?'checked':''} ${inherited.has(r.id)?'disabled':''}><span><strong>${r.id} · ${esc(r.title)}</strong><small>${esc(requirementPlacement(r))}${inherited.has(r.id)?' · inherited':''}${r.core?' · must-have':''}</small></span></label>`).join('')}</div>`,`<button data-action="close">Cancel</button><button class="primary" data-action="outcomes-save">Save applicability</button>`);}
function saveOutcomes(){const rationale=$('#scope-rationale').value.trim();if(!rationale){toast('Record a rationale for changing applicability.');return;}const c=C(),checked=new Set([...document.querySelectorAll('.outcome-check:checked')].map(x=>x.value)),base=new Set(profileRequirements(data,c.profile).map(r=>r.id));c.addedRequirements=[...checked].filter(id=>!base.has(id));c.removedRequirements=[...base].filter(id=>!checked.has(id));c.rationale=rationale;closeDialog();planningChanged();}
function reviewDialog(){showDialog('Review the current selection',`<p>Record your review of the current profile, applicability, prerequisites, course choices, tools and time budget. This is a planning review, not learner competence or operational authorisation. Descendant cohorts require their own review.</p><label>Review note<textarea id="review-note"></textarea></label>`,`<button data-action="close">Cancel</button><button class="primary" data-action="review-save">Record review</button>`);}

function showDialog(title,body,footer='',tag='WORKSHOP'){const dialog=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-top"><div><div class="eyebrow">${esc(tag)}</div><h2>${esc(title)}</h2></div><button data-action="close" aria-label="Close dialog">✕</button></div>${body}${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function closeDialog(){$('#dialog').close();}
function courseDialog(id){const c=byId.get(id);if(!c)return;const d=duration(c,S().overrides),reason=eligibility(c,audience(),S().overrides);showDialog(c.title,`<div class="chips">${pill(c.id)}${pill(c.provider)}${pill(c.type)}${pill('Source audience: '+c.level)}${pill(c.evidence,Object.keys(c.scores).length?'blue':'amber')}</div><p>${esc(c.description||'No description provided in the catalogue.')}</p><div class="field-grid"><div><h3>Learning commitment</h3><p>${esc(c.duration)}<br><strong>${d.hours===null?'Unresolved':hoursLabel(d.hours)+' budgeted'}</strong><small> · ${esc(d.note)}</small></p></div><div><h3>Access & source</h3><p>${external(c.url,'Open course / enrolment')}${c.sources.filter(u=>u!==c.url).map((u,i)=>'<br>'+external(u,'Public source '+(i+1))).join('')}</p><small>${esc(c.cost)} · ${esc(c.source.sheet)} row ${c.source.row}</small></div></div><h3>Fit and limitations</h3><p>${esc(c.limitations||'No additional fit note recorded.')}</p><p>${pill(reason||'Eligible under current recommendation filters',reason?'amber':'green')}</p>${c.audit?`<details><summary>Source review and assessment changes</summary><p>${esc(c.audit.basis)}</p><p>${esc(c.audit.note)}</p><small>${esc(c.audit.source.sheet)} row ${c.audit.source.row}</small></details>`:''}${Object.keys(c.unassessed||{}).length?`<div class="banner warn">${Object.keys(c.unassessed).length} requirements are explicitly unassessed. ${esc(Object.values(c.unassessed)[0]?.evidence||'Authoritative evidence is unavailable.')}</div>`:''}<h3>Requirement-level evidence</h3>${table(['Requirement','Score','Evidence / source'],Object.entries(c.scores).map(([id,s])=>`<tr><td>${esc(id)}<small>${esc(data.requirements.find(r=>r.id===id)?.title)}</small></td><td>${s.score}/3</td><td><div class="evidence">${esc(s.evidence)}</div><small>${esc(s.assessor)} · ${esc(s.date)} · Scores row ${s.source.row}${s.change?` · ${esc(s.change)}`:''}${Number.isInteger(s.priorScore)?` · Previous score: ${s.priorScore}/3`:''}</small></td></tr>`))}${!Object.keys(c.scores).length?'<div class="empty">Not assessed against the requirement rubric. This does not mean no teaching is present.</div>':''}`,`<button data-action="close">Close</button><button class="edit-only" data-action="estimate" data-id="${id}">Set planning hours</button><button class="primary edit-only" data-action="preview" data-id="${id}">Preview in current cohort</button>`,'COURSE DETAIL');}
function previewDialog(id){const c=byId.get(id),m=metrics(S(),C()),next=measure(m.reqs,[...m.cs,c],data.thresholds),already=m.ids.includes(id),d=duration(c,S().overrides),reason=eligibility(c,audience(),S().overrides);showDialog('Preview this course',`${courseLink(c)}<div class="stats">${stat(pct(next.coverage),'Resulting layer coverage')}${stat('+'+((next.coverage-m.m.coverage)*100).toFixed(1)+' pp','Additional coverage')}${stat(next.critical,'Remaining critical gaps')}${stat(already?'0h':d.hours===null?'Unresolved':hoursLabel(d.hours),'Additional course time')}</div><div class="preview">Current coverage ${pct(m.m.coverage)} → ${pct(next.coverage)}. ${already?'Already selected or inherited.':`Budget after addition: ${timeText({hours:m.inc.hours+(d.hours??0),unknown:m.inc.unknown+(d.hours===null?1:0)})} / ${hoursLabel(C().budget)}.`}</div>${reason?`<div class="banner warn">${esc(reason)}. Manual selection is allowed and retains this warning.</div>`:''}<h3 style="margin-top:20px">Requirements improved</h3>${table(['Requirement','Before','After'],m.reqs.filter(r=>(c.scores[r.id]?.score||0)>scoreFor(m.cs,r.id)).map(r=>`<tr><td>${r.id} · ${esc(r.title)}</td><td>${scoreFor(m.cs,r.id)}/3</td><td>${c.scores[r.id].score}/3</td></tr>`))}`,`<button data-action="close">Keep current plan</button><button class="primary edit-only" data-action="add" data-id="${id}" ${already?'disabled':''}>Add to this layer</button>`);}
function estimateDialog(id){if(!editable())return;const c=byId.get(id),d=duration(c,S().overrides);showDialog('Planning hours',`<p><strong>${esc(c.title)}</strong><br>Catalogue duration: ${esc(c.duration)}</p><p class="muted">Estimate the full course. Selecting only part of a course does not retain its full assessed coverage.</p><label>Full-course hours<input id="estimate-hours" type="number" min="0" step=".01" value="${d.hours??''}" placeholder="Enter hours"></label>`,`<button data-action="estimate-reset" data-id="${id}">Use source duration</button><button class="primary" data-action="estimate-save" data-id="${id}">Save estimate</button>`);}
function scopeDialog(){if(!editable())return;if(C().profile){outcomeDialog();return;}const c=C(),active=new Set(scope(data,c).map(r=>r.id));showDialog('Applicability & inheritance',`<p class="muted">Presets are editable proposals. Select the requirements this layer should address; source scores remain unchanged.</p><div class="field-grid"><label>Inherited pathway<select id="parent">${options(S().cohorts.filter(x=>x.id!==c.id&&!ancestors(S(),x).some(a=>a.id===c.id)).map(x=>[x.id,x.name]),c.parent||'','No inherited pathway')}</select></label><label>Audience level<select id="rank">${options([['1','Entry / all users'],['2','Practitioner'],['3','Expert']],String(c.rank))}</select></label></div><div class="field"><label>Reason for applicability changes<textarea id="scope-rationale" placeholder="Explain how this scope reflects the team’s responsibilities">${esc(c.rationale)}</textarea></label></div><div class="checkbox-list" style="max-height:360px">${data.requirements.map(r=>`<label><input class="scope-check" type="checkbox" value="${r.id}" ${active.has(r.id)?'checked':''}><span><strong>${r.id} · ${esc(r.title)}</strong><small>${esc(r.level)}${r.core?' · must-have':''} · ${esc(needMap.get(r.need)?.title)}</small></span></label>`).join('')}</div>`,`<button data-action="close">Cancel</button><button class="primary" data-action="scope-save">Save applicability</button>`);}
function eligibilityDialog(){if(!editable())return;const c=C();showDialog('Recommendation filters',`<p>These filters control automatic recommendations. Catalogue browsing remains independent.</p><label class="toggle"><input id="audience-filter" type="checkbox" ${c.filters.audience?'checked':''}> ${c.profile?'Use source audience labels for shared learning; admit recorded specialist teaching for the selected responsibilities':'Use source audience level to exclude higher or unknown levels (previous model)'}</label><p class="muted">${c.profile?'Specialist teaching is considered independently of agentic level when a course scores at least 2 on an applicable specialist outcome. This does not establish learner readiness: review role prerequisites and course fit.':'This previous-model scenario retains its original audience filtering. Create a new model-v2 plan to separate agentic level from specialist learning.'} With this filter off, all source audience levels are allowed.</p><h3>Resource types</h3><small>Leave all unchecked to allow all learning-resource types. Exam-only, unavailable and unassessed records remain excluded.</small><div class="checkbox-list">${[...new Set(data.courses.map(c=>c.type))].sort().map(t=>`<label><input class="type-check" type="checkbox" value="${esc(t)}" ${c.filters.types.includes(t)?'checked':''}>${esc(t)}</label>`).join('')}</div>`,`<button data-action="close">Cancel</button><button class="primary" data-action="eligibility-save">Save filters</button>`);}
function internalDialog(id,reqId){if(!editable())return;const item=C().internal.find(i=>i.id===id)||{id:crypto.randomUUID(),title:'',owner:'',hours:null,requirements:reqId?[reqId]:[],outcomes:'',status:'Proposed'};showDialog(id?'Edit internal work':'Plan internal learning & practice',`<div>${pill("Not in catalogue","internal-origin")}</div><p class="inline-note">Internal items are outside the catalogue. Proposed means the item still needs to be built; Ready means ready for delivery, not assessed catalogue coverage. Build items are design briefs, not available courses.</p><label>Seed from a catalogue Build brief<select id="build-seed">${options(data.buildItems.map(b=>[b.id,`${b.id} · ${b.title}`]),'','Start with a blank item')}</select></label><div class="field-grid field"><label>Title<input id="internal-title" value="${esc(item.title)}"></label><label>Owner<input id="internal-owner" value="${esc(item.owner)}" placeholder="Function / person responsible"></label><label>Learner hours (blank if unknown)<input id="internal-hours" type="number" min="0" step=".25" value="${item.hours??''}"></label><label>Status<select id="internal-status">${options([['Proposed','Proposed — to be built'],['In development','In development'],['Ready','Ready for delivery']],item.status)}</select></label></div><label>Intended outcomes<textarea id="internal-outcomes">${esc(item.outcomes)}</textarea></label><div class="field"><h3>Linked requirements</h3><div class="checkbox-list">${data.requirements.map(r=>`<label><input class="internal-req" type="checkbox" value="${r.id}" ${item.requirements.includes(r.id)?'checked':''}><span>${r.id} · ${esc(r.title)}</span></label>`).join('')}</div></div><div class="banner">Planned internal work will appear beside these gaps. It will not increase assessed course coverage.</div>`,`<button data-action="close">Cancel</button><button class="primary" data-action="internal-save" data-id="${item.id}">Save internal item</button>`);}
function scenarioDialog(){showDialog('Scenario settings',`<div class="field-grid"><label>Name<input id="scenario-name" value="${esc(S().name)}" ${readOnly()?'disabled':''}></label><label>Status<select id="scenario-status" ${readOnly()?'disabled':''}>${options(['Draft','Reviewed','Finalised'],S().status)}</select></label></div><div class="field"><label>Assumptions and decisions<textarea id="assumptions" ${readOnly()?'disabled':''}>${esc(S().assumptions)}</textarea></label></div>${S().catalogueVersion!==data.version?'<label class="toggle"><input type="checkbox" id="ack-version"> I have reviewed this plan against the current catalogue version.</label>':''}${S().schema===2&&S().modelRevision!==MODEL_REVISION?'<label class="toggle"><input type="checkbox" id="ack-model"> Apply the revised must-have applicability and mark all cohorts for selection review.</label>':''}<p class="muted">Finalised plans are read-only snapshots. Duplicate to create an editable draft. These are planning statuses, not learner sign-offs.</p>`,`<button data-action="close">Close</button>${readOnly()?'<button class="primary" data-action="duplicate">Duplicate as draft</button>':'<button class="primary" data-action="scenario-save">Save settings</button>'}`);}
function compareDialog(otherId){const other=scenarios.find(s=>s.id===otherId)||scenarios.find(s=>s.id!==activeId);if(!other){toast('Create or duplicate a second scenario to compare alternatives.');return;}showDialog('Compare plans',`<label>Compare ${esc(S().name)} with<select id="compare-select">${options(scenarios.filter(s=>s.id!==activeId).map(s=>[s.id,s.name]),other.id)}</select></label><div class="layout-gap"></div>${table(['Cohort',esc(S().name),esc(other.name)],S().cohorts.map(c=>{const o=other.cohorts.find(x=>x.id===c.id),a=metrics(S(),c),b=o?metrics(other,o):null;return `<tr><td>${esc(c.name)}</td><td><strong>${pct(a.m.coverage)}</strong> · ${timeText(a.total)} total<small>${a.m.critical} critical gaps · ${esc(c.selected.join(', ')||'no courses')}</small>${internalSummary(a.items)}</td><td>${b?`<strong>${pct(b.m.coverage)}</strong> · ${timeText(b.total)} total<small>${b.m.critical} critical gaps · ${esc(o.selected.join(', ')||'no courses')}</small>${internalSummary(b.items)}${a.reqs.map(r=>r.id).join()!==b.reqs.map(r=>r.id).join()?pill('Different applicability — not directly comparable','amber'):''}`:'Cohort not present'}</td></tr>`;}))}`,`<button data-action="close">Close</button>`);}
function importDialog(){showDialog('Import a scenario',`<p>Choose an exported JSON file or paste its contents. Import creates a separate scenario and preserves the current plan.</p><button data-action="import-file">Choose JSON file</button><div class="field"><label>Scenario JSON<textarea id="import-text" rows="10" placeholder="Paste exported JSON here"></textarea></label></div>`,`<button data-action="close">Cancel</button><button class="primary" data-action="import-text">Import pasted scenario</button>`);}
function importScenario(text){const {scenario,warnings:w}=deserialize(text,data);scenario.id=crypto.randomUUID();scenario.name+=' (imported)';scenarios.push(scenario);activeId=scenario.id;cohortId=scenario.cohorts[0].id;closeDialog();changed();toast(w.length?'Imported with warnings. Review unresolved references.':'Scenario imported.');}

let worker,timer;
async function recommend(){if(!editable())return;let problem;try{const v=$('#budget')?.value;if(v!==undefined){if(v===''||!Number.isFinite(+v)||+v<0)throw Error('Enter a valid non-negative course budget.');C().budget=+v;save();}problem=prepareProblem(data,audience(),scope(data,C(),S()),courses(selectedIds(S(),C(),false)),S().overrides);}catch(e){toast(e.message);return;}busy=true;render();try{worker=createSolverWorker();}catch(e){busy=false;render();toast('Solver could not start: '+e.message);return;}timer=setTimeout(()=>{worker.terminate();busy=false;render();toast('Solver exceeded its response deadline. Existing selections are unchanged.');},20000);worker.onmessage=({data:r})=>{clearTimeout(timer);worker.terminate();busy=false;if(r.error){render();toast(r.error);}else{proposal=r.result;render();toast('Recommendation ready for review. Your selection has not changed.');}};worker.onerror=e=>{clearTimeout(timer);worker.terminate();busy=false;render();toast('Solver could not start: '+e.message);};worker.postMessage(problem);}
function clearFilters(){search=needFilter=providerFilter=typeFilter=toolFilter=levelFilter=assessmentFilter=trackFilter=maxHours=requirementFilter='';page=0;}
let exportUrl;
function download(filename,body,type){if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(new Blob([body],{type}));showDialog('Export ready',`<p>Your file has been prepared locally.</p><p><a class="download-link" href="${exportUrl}" download="${esc(filename)}">Download ${esc(filename)} ↓</a></p><small>Save JSON to reload a complete scenario; CSV is for review. If your embedded browser does not support downloads, open this app in a standard browser, or copy the contents below into a file.</small><details class="field"><summary>View / copy file contents</summary><textarea id="export-content" readonly aria-label="Export contents" rows="12">${esc(body)}</textarea></details>`,`<button data-action="close">Close</button>`,'LOCAL EXPORT');}
const safeName=()=>S().name.replace(/[^a-z0-9_-]/gi,'-').slice(0,70);
function exportCourses(){const rows=[['Scenario','Status','Catalogue version','Assumptions','Cohort','Applicability rationale','Inherited from','Item kind','ID','Title','Hours','Original duration','URL','Owner','Item status','Evidenced outcomes / intended internal outcomes','Layer budget','Cumulative known hours','Unresolved items','Capability model','Agentic profile','Tools used']];for(const c of S().cohorts){const push=row=>rows.push([...row,S().modelVersion||1,profileLabel(c),(c.profile?.tools||[]).join('; ')]);const m=metrics(S(),c),parent=S().cohorts.find(x=>x.id===c.parent)?.name||'';for(const id of m.ids){const x=byId.get(id);push([S().name,S().status,data.version,S().assumptions,c.name,c.rationale,parent,c.selected.includes(id)?'Selected course':'Inherited course',id,x?.title||'Unresolved',x?duration(x,S().overrides).hours:'',x?.duration,x?.url,'','',x?m.cum.rows.filter(r=>(x.scores[r.id]?.score||0)>0).map(r=>r.id).join(', '):'',c.budget,m.total.hours,m.total.unknown]);}for(const i of m.items)push([S().name,S().status,data.version,S().assumptions,c.name,c.rationale,parent,'Internal work — not in catalogue',i.id,i.title,i.hours,'','',''+i.owner,internalStatusLabel(i),i.requirements.join(', ')+'; '+i.outcomes,c.budget,m.total.hours,m.total.unknown]);if(!m.ids.length&&!m.items.length)push([S().name,S().status,data.version,S().assumptions,c.name,c.rationale,parent,'Empty cohort','','','','','','','','',c.budget,0,0]);}download(safeName()+'-course-plan.csv',csv(rows),'text/csv');}
function exportGaps(){const rows=[['Scenario','Catalogue version','Cohort','Applicability rationale','Requirement','Need','Description','Core','Selected score','Assessed in selection','Catalogue maximum','Classification','Improving courses','Course URLs','Planned internal work','Owners','Internal hours','Assumptions','Capability model','Agentic profile','Tools used']];for(const c of S().cohorts){const push=row=>rows.push([...row,S().modelVersion||1,profileLabel(c),(c.profile?.tools||[]).join('; ')]);const m=metrics(S(),c);for(const r of m.m.rows){const best=scoreFor(data.courses,r.id),improve=data.courses.filter(x=>(x.scores[r.id]?.score||0)>r.score),items=m.items.filter(i=>i.requirements.includes(r.id));push([S().name,data.version,c.name,c.rationale,r.id,r.need,r.description,r.core,r.score,r.assessed,best,gapType(r.score,best),improve.map(x=>x.id).join('; '),improve.map(x=>x.url).join('; '),items.map(i=>i.title+' ['+internalStatusLabel(i)+'; not in catalogue]').join('; '),items.map(i=>i.owner).join('; '),items.map(i=>i.hours??'Unknown').join('; '),S().assumptions]);}}download(safeName()+'-gap-register.csv',csv(rows),'text/csv');}
function printPlan(){return `<div class="print-header"><div class="eyebrow">CYBER / CAPABILITY PLANNER</div><p class="print-release">${esc(releaseLabel)}</p><h1>${esc(S().name)}</h1><p>${esc(S().status)} · ${esc(data.filename)} · snapshot ${data.version}</p><p>${esc(S().assumptions)}</p><p>Capability model ${S().modelVersion||1}${S().schema===1?' (previous model; original scope retained)':' — Foundation + agentic level + role specialisms + tool training'}. Coverage is assessed syllabus evidence, not demonstrated competence or operational permission.</p></div>${S().cohorts.map(c=>{const m=metrics(S(),c);return `<article class="print-cohort"><h2>${esc(c.group)} / ${esc(c.name)}</h2><p>${pct(m.m.coverage)} layer coverage · ${m.m.critical} critical gaps · ${timeText(m.inc)} additional courses / ${hoursLabel(c.budget)} budget · ${timeText(m.total)} cumulative learner commitment</p><p>${esc(profileLabel(c))}<br>Tools: ${esc(c.profile?.tools.join(', ')||'Not assigned')}<br>Applicable requirements: ${m.reqs.map(r=>r.id).join(', ')}<br>Inheritance: ${ancestors(S(),c).map(x=>esc(x.name)).join(' → ')||'None'}<br>${esc(c.rationale||c.note||'Default scope')}</p>${table(['Course','Learning time','Link'],m.ids.map(id=>{const x=byId.get(id);return `<tr><td>${id} · ${esc(x?.title||'Unresolved')}</td><td>${x?duration(x,S().overrides).hours??'Unknown':'Unknown'}</td><td>${x?external(x.url,x.url):''}</td></tr>`;}))}<h3>Internal commitments — not in catalogue</h3><p>Development status is separate from assessed coverage. Planned internal work contributes learner time only.</p>${m.items.length?table(['Item / owner','Hours / status','Intended outcomes / requirements'],m.items.map(i=>`<tr><td>${esc(i.title)} / ${esc(i.owner)}</td><td>${i.hours===null?'Time unresolved':hoursLabel(i.hours)}<br>${internalBadges(i)}</td><td>${esc(i.outcomes)} · ${esc(i.requirements.join(', '))}</td></tr>`)):'<p>No internal work planned.</p>'}<h3>Remaining evidence gaps</h3>${table(['Requirement','Selected / ceiling','Next step'],m.m.rows.filter(r=>r.score<3).map(r=>`<tr><td>${r.id} · ${esc(r.title)}${r.core?' (must-have)':''}</td><td>${r.score} / ${scoreFor(data.courses,r.id)}</td><td>${gapType(r.score,scoreFor(data.courses,r.id))}</td></tr>`))}</article>`;}).join('')}`;}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{
 if(a==='close'){closeDialog();return;}
 if(a==='course'){courseDialog(id);return;}
 if(a==='preview'){previewDialog(id);return;}
 if(a==='view'){view=id;clearFilters();render();return;}
 if(a==='open-cohort'){if(busy){toast('Cancel or finish the current recommendation first.');return;}cohortId=id;view='planner';proposal=null;clearFilters();render();return;}
 if(a==='presentation'){presentation=!presentation;render();return;}
 if(a==='profile'){profileDialog();return;}
 if(a==='scope'){scopeDialog();return;}
 if(a==='export-crosswalk'){download('capability-crosswalk.json',JSON.stringify({modelVersion:MODEL_VERSION,modelRevision:MODEL_REVISION,retiredOutcomes:RETIRED_OUTCOMES,catalogueVersion:data.version,requirements:crosswalk(data)},null,2),'application/json');return;}
 if(a==='tool-training'||a==='profile-tool'){view='catalogue';clearFilters();if(a==='tool-training')trackFilter='tool';else if(data.courses.some(c=>c.tool===id))toolFilter=id;else search=id;render();return;}
 if(a==='eligibility'){eligibilityDialog();return;}
 if(a==='recommend'){recommend();return;}
 if(a==='cancel-solve'){worker?.terminate();clearTimeout(timer);busy=false;render();return;}
 if(a==='supplements'){requirementFilter=id;view='catalogue';search=needFilter='';page=0;render();return;}
 if(a==='clear-filters'){clearFilters();render();return;}
 if(a==='next'||a==='previous'){page+=a==='next'?1:-1;render();return;}
 if(a==='scenario-settings'){scenarioDialog();return;}
 if(a==='compare'){compareDialog();return;}
 if(a==='export-json'){download(safeName()+'.json',serialize(S()),'application/json');return;}
 if(a==='export-courses'){exportCourses();return;}
 if(a==='export-gaps'){exportGaps();return;}
 if(a==='print'){window.print();return;}
 if(a==='import'){if(!busy)importDialog();return;}
 if(a==='import-file'){$('#import-file').click();return;}
 if(a==='import-text'){importScenario($('#import-text').value);return;}
 if(a==='new'||a==='duplicate'){if(busy)return;const s=a==='new'?createScenario(data,'New plan'):duplicateScenario(S());scenarios.push(s);activeId=s.id;cohortId='all';closeDialog();changed();return;}
 if(!editable())return;
 const c=C();
 if(a==='estimate'){estimateDialog(id);return;}
 if(a==='internal-new'||a==='internal-edit'||a==='internal-for'){internalDialog(a==='internal-edit'?id:null,a==='internal-for'?id:null);return;}
 if(a==='add'){if(!selectedIds(S(),c).includes(id))c.selected.push(id);c.excluded=c.excluded.filter(x=>x!==id);closeDialog();planningChanged();return;}
 if(a==='remove'){c.selected=c.selected.filter(x=>x!==id);c.pinned=c.pinned.filter(x=>x!==id);planningChanged();return;}
 if(a==='pin'){c.pinned=c.pinned.includes(id)?c.pinned.filter(x=>x!==id):[...c.pinned,id];planningChanged();return;}
 if(a==='exclude'){if(c.excluded.includes(id))c.excluded=c.excluded.filter(x=>x!==id);else{c.excluded.push(id);c.selected=c.selected.filter(x=>x!==id);c.pinned=c.pinned.filter(x=>x!==id);}planningChanged();return;}
 if(a==='apply-proposal'){const result=proposal;invalidateRecommendations(S(),c);c.selected=[...result.ids];c.pinned=c.pinned.filter(id=>c.selected.includes(id));c.needsReview=false;c.recommendation={message:result.message,status:result.status,date:new Date().toISOString()};changed();return;}
 if(a==='discard-proposal'){proposal=null;render();return;}
 if(a==='estimate-save'){const v=$('#estimate-hours').value;if(v===''||!Number.isFinite(+v)||+v<0){toast('Enter valid non-negative hours.');return;}S().overrides[id]=+v;for(const item of S().cohorts)if(item.selected.includes(id))invalidateRecommendations(S(),item);closeDialog();changed();return;}
 if(a==='estimate-reset'){delete S().overrides[id];for(const item of S().cohorts)if(item.selected.includes(id))invalidateRecommendations(S(),item);closeDialog();changed();return;}
 if(a==='profile-save'){saveProfile();return;}
 if(a==='outcomes-save'){saveOutcomes();return;}
 if(a==='review-selection'){reviewDialog();return;}
 if(a==='review-save'){const note=$('#review-note').value.trim();if(!note){toast('Record what you reviewed.');return;}c.needsReview=false;c.review={date:new Date().toISOString(),note};closeDialog();changed();return;}
 if(a==='scope-save'){const rationale=$('#scope-rationale').value.trim();if(!rationale){toast('Record a rationale for changing applicability.');return;}const checked=[...document.querySelectorAll('.scope-check:checked')].map(x=>x.value);if(!checked.length){toast('Choose at least one applicable requirement.');return;}c.parent=$('#parent').value||null;c.rank=+$('#rank').value;c.addedRequirements=checked;c.removedRequirements=data.requirements.filter(r=>!checked.includes(r.id)).map(r=>r.id);c.needs=[...new Set(data.requirements.filter(r=>checked.includes(r.id)).map(r=>r.need))];c.rationale=rationale;closeDialog();changed();return;}
 if(a==='eligibility-save'){c.filters={audience:$('#audience-filter').checked,types:[...document.querySelectorAll('.type-check:checked')].map(x=>x.value)};closeDialog();planningChanged();return;}
 if(a==='internal-save'){const title=$('#internal-title').value.trim(),v=$('#internal-hours').value,requirements=[...document.querySelectorAll('.internal-req:checked')].map(x=>x.value);if(!title||!requirements.length||v!==''&&(!Number.isFinite(+v)||+v<0)){toast('Enter a title, valid hours (or leave blank), and at least one requirement.');return;}const item={id,title,owner:$('#internal-owner').value.trim(),hours:v===''?null:+v,requirements,outcomes:$('#internal-outcomes').value.trim(),status:$('#internal-status').value};c.internal=c.internal.filter(x=>x.id!==id);c.internal.push(item);closeDialog();changed();return;}
 if(a==='internal-remove'){c.internal=c.internal.filter(x=>x.id!==id);changed();return;}
 if(a==='scenario-save'){const name=$('#scenario-name').value.trim();if(!name){toast('Name this scenario.');return;}if($('#ack-version')?.checked)S().catalogueVersion=data.version;if($('#ack-model')?.checked){S().modelRevision=MODEL_REVISION;for(const item of S().cohorts)invalidateRecommendations(S(),item);}if($('#scenario-status').value==='Finalised'&&warnings().length){toast('Resolve catalogue/version warnings before finalising.');return;}S().name=name;S().status=$('#scenario-status').value;S().assumptions=$('#assumptions').value;closeDialog();changed();return;}
 }catch(err){toast(err.message);}});
document.addEventListener('change',e=>{const id=e.target.id;try{
 if(id==='scenario-select'||id==='cohort-nav'){if(busy){toast('Cancel or finish the current recommendation first.');render();return;}if(id==='scenario-select')activeId=e.target.value;else cohortId=e.target.value;proposal=null;clearFilters();save();render();return;}
 if(id==='profile-level'){const c=C(),level=+e.target.value,parents=profileParents(c,level),best=parents.filter(p=>p.profile.level===level).at(-1)||parents.at(-1);$('#profile-parent').innerHTML=options(parents.map(p=>[p.id,p.name]),best?.id||'','No inherited selection');return;}
 if(id==='budget'){if(!editable())return;const v=e.target.value;if(v===''||+v<0||!Number.isFinite(+v)){toast('Enter a valid budget.');render();return;}C().budget=+v;planningChanged();return;}
 const map={'track-filter':v=>trackFilter=v,'need-filter':v=>needFilter=v,'provider-filter':v=>providerFilter=v,'type-filter':v=>typeFilter=v,'tool-filter':v=>toolFilter=v,'level-filter':v=>levelFilter=v,'assessment-filter':v=>assessmentFilter=v,'max-hours':v=>maxHours=v,'sort':v=>sort=v};if(map[id]){map[id](e.target.value);page=0;render();return;}
 if(id==='compare-select'){compareDialog(e.target.value);return;}
 if(id==='build-seed'){const b=data.buildItems.find(b=>b.id===e.target.value);if(b){$('#internal-title').value=b.title;$('#internal-outcomes').value=b.description+(b.note?' '+b.note:'');}return;}
 }catch(err){toast(err.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='budget'&&!readOnly()&&!busy){const v=e.target.value;if(v!==''&&Number.isFinite(+v)&&+v>=0){C().budget=+v;invalidateRecommendations(S(),C());proposal=null;save();}}if(e.target.id==='search'){search=e.target.value;clearTimeout(searchTimer);// Keep the input node intact so refreshes preserve the caret, selection and focus.
searchTimer=setTimeout(()=>{const results=$('#catalogue-results');if(view!=='catalogue'||!results)return;page=0;results.innerHTML=candidateTable(true);},300);}});
$('#import-file').addEventListener('change',async e=>{try{if(busy)return;const file=e.target.files[0];if(file)importScenario(await file.text());}catch(err){toast(err.message);}finally{e.target.value='';}});
render();
